import { useState } from "react";

export function Cart() {
  const [total, setTotal] = useState(0);

  function addItem(price: number) {
    setTotal(total + price); // queues "replace with total + price"
  }

  function addBundle() {
    addItem(120); // replace with 0 + 120
    addItem(80); // replace with 0 + 80, and the last one wins
  }

  return <button onClick={addBundle}>Add bundle ({total} EGP)</button>;
}

import { useState } from "react";

export function Cart() {
  const [total, setTotal] = useState(0);

  function addItem(price: number) {
    setTotal((t) => t + price); // queues "add price to the latest value"
  }

  function addBundle() {
    addItem(120); // 0 → 120
    addItem(80); // 120 → 200
  }

  return <button onClick={addBundle}>Add bundle ({total} EGP)</button>;
}

